// ============================================================
// Tier 3 : création d'une escalade + email à Amir
// ============================================================
const body = $input.item.json.body || $input.item.json;
const N8N_BASE = $env['N8N_WEBHOOK_BASE_URL'] || 'http://localhost:5678';
const SUPA_URL = $env['SUPABASE_URL'];
const SUPA_KEY = $env['SUPABASE_SERVICE_KEY'];

// Valider les champs requis
const required = ['agent_id', 'action', 'description'];
for (const f of required) {
  if (!body[f]) throw new Error(`Champ requis manquant : ${f}`);
}

// 1. INSERT dans escalations
const insertResp = await $http.request({
  method: 'POST',
  url: `${SUPA_URL}/rest/v1/escalations`,
  headers: {
    'apikey': SUPA_KEY,
    'Authorization': `Bearer ${SUPA_KEY}`,
    'Content-Type': 'application/json',
    'Prefer': 'return=representation'
  },
  body: {
    agent_id:    body.agent_id,
    action:      body.action,
    description: body.description,
    context:     body.context  || null,
    content:     body.content  || null,
    status:      'pending'
  },
  json: true
});

const escalation = insertResp.body[0];
const uuid = escalation.id;
const approveUrl = `${N8N_BASE}/webhook/tier3-approve?id=${uuid}`;
const rejectUrl  = `${N8N_BASE}/webhook/tier3-reject?id=${uuid}`;
const expiresAt  = escalation.expires_at;

// 2. Corps de l'email Tier 3
const emailSubject = `[TIER 3] Action requise — ${body.agent_id} — ${body.action}`;
const emailBody = [
  `Agent : ${body.agent_id}`,
  `Action : ${body.description}`,
  ``,
  `Contexte :`,
  body.context || '(aucun contexte fourni)',
  ``,
  body.content ? `Contenu :\n${body.content}\n` : '',
  `→ APPROUVER : ${approveUrl}`,
  `→ REJETER   : ${rejectUrl}`,
  ``,
  `ID escalade : ${uuid}`,
  `Expiration  : 24h (${expiresAt})`
].join('\n');

// 3. Log création
const logT0 = Date.now();
await $http.request({
  method: 'POST',
  url: `${SUPA_URL}/rest/v1/agent_logs`,
  headers: {
    'apikey': SUPA_KEY,
    'Authorization': `Bearer ${SUPA_KEY}`,
    'Content-Type': 'application/json',
    'Prefer': 'return=minimal'
  },
  body: {
    agent_id:    'karim',
    action:      'tier3_escalation_created',
    input:       { escalation_id: uuid, agent_id: body.agent_id, action: body.action },
    output:      { uuid, approveUrl, rejectUrl },
    tier:        3,
    duration_ms: Date.now() - logT0,
    status:      'pending'
  },
  json: true
});

return [{ json: {
  escalation_id: uuid,
  emailSubject,
  emailBody,
  approveUrl,
  rejectUrl,
  expiresAt,
  agent_id: body.agent_id,
  action:   body.action
}}];

// ============================================================
// Tier 3 : résolution APPROVE
// ============================================================
const uuid = $input.item.json.query?.id || $input.item.json.id;
if (!uuid) throw new Error('Paramètre ?id manquant dans la requête APPROVE');

const SUPA_URL = $env['SUPABASE_URL'];
const SUPA_KEY = $env['SUPABASE_SERVICE_KEY'];

// Récupérer l'escalade
const getResp = await $http.request({
  method: 'GET',
  url: `${SUPA_URL}/rest/v1/escalations?id=eq.${uuid}&select=*`,
  headers: { 'apikey': SUPA_KEY, 'Authorization': `Bearer ${SUPA_KEY}` },
  json: true
});
const esc = getResp.body[0];
if (!esc) throw new Error(`Escalade introuvable : ${uuid}`);
if (esc.status !== 'pending') throw new Error(`Escalade déjà résolue (${esc.status}) : ${uuid}`);
if (new Date(esc.expires_at) < new Date()) throw new Error(`Escalade expirée : ${uuid}`);

// Mettre à jour le statut
await $http.request({
  method: 'PATCH',
  url: `${SUPA_URL}/rest/v1/escalations?id=eq.${uuid}`,
  headers: {
    'apikey': SUPA_KEY,
    'Authorization': `Bearer ${SUPA_KEY}`,
    'Content-Type': 'application/json',
    'Prefer': 'return=minimal'
  },
  body: { status: 'approved', resolved_at: new Date().toISOString(), resolved_by: 'amir_email' },
  json: true
});

// Log
await $http.request({
  method: 'POST',
  url: `${SUPA_URL}/rest/v1/agent_logs`,
  headers: {
    'apikey': SUPA_KEY, 'Authorization': `Bearer ${SUPA_KEY}`,
    'Content-Type': 'application/json', 'Prefer': 'return=minimal'
  },
  body: {
    agent_id: 'karim', action: 'tier3_escalation_approved',
    input: { escalation_id: uuid },
    output: { agent_id: esc.agent_id, action: esc.action, resolved_by: 'amir_email' },
    tier: 3, duration_ms: 0, status: 'success'
  },
  json: true
});

// Notifier l'agent d'origine
const N8N_BASE = $env['N8N_WEBHOOK_BASE_URL'] || 'http://localhost:5678';
await $http.request({
  method: 'POST',
  url: `${N8N_BASE}/webhook/agent-${esc.agent_id}-resume`,
  body: { escalation_id: uuid, status: 'approved', action: esc.action, context: esc.context },
  json: true
}).catch(() => {});

return [{ json: { success: true, escalation_id: uuid, status: 'approved', agent: esc.agent_id } }];

// ============================================================
// Tier 3 : résolution REJECT
// ============================================================
const uuid = $input.item.json.query?.id || $input.item.json.id;
if (!uuid) throw new Error('Paramètre ?id manquant dans la requête REJECT');

const SUPA_URL = $env['SUPABASE_URL'];
const SUPA_KEY = $env['SUPABASE_SERVICE_KEY'];

// Récupérer l'escalade
const getResp = await $http.request({
  method: 'GET',
  url: `${SUPA_URL}/rest/v1/escalations?id=eq.${uuid}&select=*`,
  headers: { 'apikey': SUPA_KEY, 'Authorization': `Bearer ${SUPA_KEY}` },
  json: true
});
const esc = getResp.body[0];
if (!esc) throw new Error(`Escalade introuvable : ${uuid}`);
if (esc.status !== 'pending') throw new Error(`Escalade déjà résolue (${esc.status}) : ${uuid}`);

// Mettre à jour le statut
await $http.request({
  method: 'PATCH',
  url: `${SUPA_URL}/rest/v1/escalations?id=eq.${uuid}`,
  headers: {
    'apikey': SUPA_KEY,
    'Authorization': `Bearer ${SUPA_KEY}`,
    'Content-Type': 'application/json',
    'Prefer': 'return=minimal'
  },
  body: { status: 'rejected', resolved_at: new Date().toISOString(), resolved_by: 'amir_email' },
  json: true
});

// Log
await $http.request({
  method: 'POST',
  url: `${SUPA_URL}/rest/v1/agent_logs`,
  headers: {
    'apikey': SUPA_KEY, 'Authorization': `Bearer ${SUPA_KEY}`,
    'Content-Type': 'application/json', 'Prefer': 'return=minimal'
  },
  body: {
    agent_id: 'karim', action: 'tier3_escalation_rejected',
    input: { escalation_id: uuid },
    output: { agent_id: esc.agent_id, action: esc.action, resolved_by: 'amir_email' },
    tier: 3, duration_ms: 0, status: 'success'
  },
  json: true
});

// Notifier l'agent d'origine de l'annulation
const N8N_BASE = $env['N8N_WEBHOOK_BASE_URL'] || 'http://localhost:5678';
await $http.request({
  method: 'POST',
  url: `${N8N_BASE}/webhook/agent-${esc.agent_id}-resume`,
  body: { escalation_id: uuid, status: 'rejected', action: esc.action, context: esc.context },
  json: true
}).catch(() => {});

return [{ json: { success: true, escalation_id: uuid, status: 'rejected', agent: esc.agent_id } }];

// Marque les escalades expirées
const SUPA_URL = $env['SUPABASE_URL'];
const SUPA_KEY = $env['SUPABASE_SERVICE_KEY'];

const resp = await $http.request({
  method: 'PATCH',
  url: `${SUPA_URL}/rest/v1/escalations?status=eq.pending&expires_at=lt.${new Date().toISOString()}`,
  headers: {
    'apikey': SUPA_KEY,
    'Authorization': `Bearer ${SUPA_KEY}`,
    'Content-Type': 'application/json',
    'Prefer': 'return=representation'
  },
  body: { status: 'expired', resolved_at: new Date().toISOString(), resolved_by: 'system_cron' },
  json: true
});

const expired = resp.body || [];
if (expired.length > 0) {
  await $http.request({
    method: 'POST',
    url: `${SUPA_URL}/rest/v1/agent_logs`,
    headers: {
      'apikey': SUPA_KEY, 'Authorization': `Bearer ${SUPA_KEY}`,
      'Content-Type': 'application/json', 'Prefer': 'return=minimal'
    },
    body: {
      agent_id: 'karim', action: 'tier3_escalations_expired',
      input: {}, output: { count: expired.length, ids: expired.map(e => e.id) },
      tier: 3, duration_ms: 0, status: 'success'
    },
    json: true
  });
}

return [{ json: { expired_count: expired.length, timestamp: new Date().toISOString() } }];
